// spirvFor is a rung's build for a bank. Every rung has all three.
func (v hcVariant) spirvFor(b DenseBank) []byte {
	switch b {
	case BankQ8:
		return v.q8
	case BankQ4K:
		return v.q4
	case BankQ5K:
		return v.q5
	}
	return v.spirv
}

