void main() {
    uint tid = gl_LocalInvocationID.x;
    uint tileIdx = gl_WorkGroupID.y;
    // The grid is the same static upper bound the GEMM's is, and the same
    // early return: the schedule's real length lives on the device.
    //
    // **The shared expert is the schedule's last tile** (TODO.md P22, the
    // eleventh tile). It is the same shape as a routed expert and runs for
    // every token, and until P22 it was two dispatches of its own — one
    // group of the same kernel over the identity permutation at the front
    // of the row space — at half the bus, because a 1-2 MB dispatch is
    // mostly launch and tail (research/p19-decode-attribution.md). When the
    // host names its bank in MOE_SH_B (NO_W otherwise) the dispatch carries
    // one tile past the routed count, whose record is not in the list: its
    // rows are the reserve at the front of the row space (the identity the
    // host wrote), every token of the batch is real, and its bank rows are
    // MOE_SH_B's rather than expert-major rows of `bOff`. The host only does
    // it when the shared bank is the routed bank's format, since the format
    // is compiled in.
    uint nTiles = actu[pc.moeTileOff];
    bool shTile = false;
    if (MOE_SH_B != NO_W) {
        if (tileIdx > nTiles) {
            return;
        }
        shTile = (tileIdx == nTiles);
    } else if (tileIdx >= nTiles) {
        return;
    }
    uint expert = 0u;
    uint rowStart = 0u;
    // The real rows; the rest of the tile is padding (see the header). Every
    // guard below tests ROWS as well, which is a constant, so that a one-row
    // build still compiles to one row's code.
    uint real = pc.tokens;
    if (!shTile) {
        uint rec = pc.moeTileOff + 2u + 3u * tileIdx;
        expert = actu[rec];
        rowStart = actu[rec + 1u];
        real = actu[rec + 2u];
    }
