			multi := run(0, rows, HCUpGemv)
			gemm := run(0, rows, HCUpM1)
			for r := 0; r < rows; r++ {
				single := run(r, 1, HCUpGemv)
				rs, err := compare(multi[r*n:(r+1)*n], single[:n])
				if err != nil {
